import React,{useState,useRef,useEffect}from'react';import{Folder,File,FileText,Table2,Globe,Code2,Activity,Settings,Play,Pause,Square,SkipForward,RotateCcw,Repeat,Plus,X,Check,ChevronRight,ChevronLeft,ChevronDown,ArrowLeft,ArrowUp,ArrowUpRight,ArrowDownToLine,ArrowUpFromLine,Copy,Clipboard,Pencil,Trash2,Search,Save,Undo2,Redo2,Bold,AlignLeft,Link2,Unlink,Layers,Camera,GitBranch,Clock,Bell,Calendar,Timer,StickyNote,Monitor,Sun,Moon,Volume2,Wifi,Wind,Navigation,Target,AlertTriangle,FolderOpen,CheckCircle2,MoreHorizontal,Send,Maximize2,Terminal,Download,RefreshCw,ExternalLink,MoveRight,BookOpen}from'lucide-react';
import{engine,Button,Mini,Dialog,Icon,colors,fmtTime}from'./main.jsx';import{APP_NAMES}from'./engine.mjs';import{clone}from'./vm.mjs';import{address,parseCell,parseRange}from'./sheet.mjs';import{SceneView}from'./scene.jsx';
export function Apps({w,source}){if(w.appId==='projection'){if(!source)return<div className="empty"><Monitor/><h3>源应用已关闭</h3></div>;const view={...source,data:w.data.view};return<div className="projection-content"><div className="projection-banner"><span className="status-dot"/><b>{source.systemId}</b><ChevronRight size={12}/><span>{source.title}</span><span className="projection-live">{engine.blockedReason(source.systemId)||'实时投送 · 双向交互'}</span></div><div className="projection-inner">{source.appId==='player'?<Player w={view} control={w}/>:<Charts w={view} control={w}/>}</div></div>}
 const map={files:Files,spreadsheet:Sheet,widgets:Widgets,editor:Editor,browser:Browser,tasks:Tasks,settings:Preferences,systems:Systems,player:Player,charts:Charts,help:Help};const C=map[w.appId];return C?<C w={w}/>:null}
const fileApp=f=>f.type==='folder'?'files':f.path.endsWith('.sheet')?'spreadsheet':/\.(scene|flight)$/.test(f.path)?'player':/\.snapshot$/.test(f.path)?'systems':'editor';
function Files({w}){const s=engine.system(w.systemId),d=w.data;const [dialog,setDialog]=useState(null),[name,setName]=useState(''),[menu,setMenu]=useState(null),[dragging,setDragging]=useState(false),[filter,setFilter]=useState('');const items=Object.values(s.files).filter(f=>f.path.substring(0,f.path.lastIndexOf('/'))===d.path&&f.name.toLowerCase().includes(filter.toLowerCase())).sort((a,b)=>a.type===b.type?a.name.localeCompare(b.name):a.type==='folder'?-1:1);const selected=()=>d.selected.map(p=>s.files[p]).filter(Boolean);
 const navigate=p=>{d.path=p;d.selected=[];engine.emit()};
 const act=(type)=>{setMenu(null);if(type==='copy'||type==='cut'){engine.fileClipboard={sid:s.id,paths:[...d.selected],cut:type==='cut'};engine.notify(s.id,d.selected.length+' 项已'+(type==='cut'?'剪切':'复制'))}if(type==='paste'){const c=engine.fileClipboard;if(c)transfer(c.sid,c.paths,c.cut)}if(type==='delete'||type==='restore')engine.dispatch(w,{type:'files',action:type,paths:[...d.selected],notice:type==='delete'?'文件已移入回收站':'文件已还原'});if(type==='rename'){setName(selected()[0]?.name||'');setDialog('rename')}if(type==='file'||type==='folder'){setName(type==='folder'?'新建文件夹':'未命名.txt');setDialog(type)}engine.emit()};
 const transfer=(from,paths,cut=false)=>{const src=engine.system(from);if(!src)return;const conflicts=paths.filter(p=>s.files[d.path+'/'+src.files[p]?.name]);const execute=()=>{const entries=[],sourcePaths=[];for(const path of paths){const f=src.files[path];if(!f)continue;const target=d.path+'/'+f.name;if(s.id===from&&(target===path||target.startsWith(path+'/')))continue;for(const sub of Object.values(src.files).filter(x=>x.path===path||x.path.startsWith(path+'/'))){entries.push({path:target+sub.path.slice(path.length),content:sub.content,type:sub.type});sourcePaths.push(sub.path)}}engine.dispatch(w,{type:'files',action:'transfer',entries,sourceId:from,sourcePaths,cut,notice:paths.length+' 个文件已'+(cut?'移动':'复制')+'到 '+s.name+d.path});setDialog(null);if(s.parentId)engine.notify(s.id,'传递已排队，文件进程正在处理…')};if(conflicts.length){setDialog({type:'overwrite',execute});return}execute()};
 const confirm=()=>{if(!name.trim()||name.includes('/'))return;const path=d.path+'/'+name.trim();engine.dispatch(w,{type:'files',action:dialog==='rename'?'rename':'create',path,paths:[...d.selected],kind:dialog==='folder'?'folder':'file'});setDialog(null)};
 return<div className="files-app app-shell"><div className="app-toolbar"><Button icon={Plus} testId="files-new-file" onClick={()=>act('file')}>新建</Button><Mini icon={Folder} label="新建文件夹" testId="files-new-folder" onClick={()=>act('folder')}/><i/><Mini icon={Copy} label="复制" testId="files-copy" onClick={()=>act('copy')}/><Mini icon={Clipboard} label="粘贴" testId="files-paste" onClick={()=>act('paste')}/><Mini icon={Pencil} label="重命名" onClick={()=>act('rename')}/><Mini icon={Trash2} label="删除" onClick={()=>act('delete')}/><i/><Mini icon={ArrowUpFromLine} label="从本机导入" onClick={async()=>{const fs=await window.host?.importFile();engine.dispatch(w,{type:'files',action:'transfer',entries:(fs||[]).map(f=>({path:d.path+'/'+f.name,content:f.content,type:'file'})),notice:'导入完成'})}}/><Mini icon={ArrowDownToLine} label="保存到本机" onClick={()=>{const f=selected()[0];if(f)window.host?.exportFile(f)}}/><span className="spacer"/><span className="toolbar-muted">{s.id} 的文件</span></div>
 <div className="file-location"><Mini icon={ArrowLeft} label="返回上一级" onClick={()=>navigate(d.path.substring(0,d.path.lastIndexOf('/'))||'/')}/><Mini icon={ArrowUp} label="上一级" onClick={()=>navigate(d.path.substring(0,d.path.lastIndexOf('/'))||'/')}/><div className="path-box"><Folder size={16}/><input data-testid="files-path" aria-label="文件路径" value={d.path} onChange={e=>{d.path=e.target.value;engine.emit()}}/></div><div className="file-search"><Search size={15}/><input placeholder="搜索此文件夹" value={filter} onChange={e=>setFilter(e.target.value)}/></div></div>
 <div className="split-content"><aside className="file-sidebar"><div className="sidebar-title">工作空间</div>{[['/Demo','演示素材',Layers],['/Documents','文档',FileText],['/Downloads','下载',Download],['/Programs','程序',Code2],['/System','系统源文件',Settings],['/Snapshots','快照',Camera],['/Recycle','回收站',Trash2]].map(([path,label,I])=><button key={path} data-testid="files-nav" data-file-path={path} className={d.path===path?'active':''} onClick={()=>navigate(path)}><I size={17}/>{label}</button>)}<div className="storage-card"><span><Monitor size={15}/> {s.name}</span><div className="meter"><i style={{width:Math.min(100,engine.storageUsed(s)/s.storageLimit*100)+'%'}}/></div><small>{(engine.storageUsed(s)/1024).toFixed(0)} KB / {s.storageLimit/1024/1024} MB</small></div></aside>
 <div className={'files-main '+(dragging?'drop-target':'')} data-testid="files-list" onDragOver={e=>{e.preventDefault();e.stopPropagation();setDragging(true)}} onDragLeave={()=>setDragging(false)} onDrop={e=>{e.preventDefault();e.stopPropagation();setDragging(false);try{const payload=JSON.parse(e.dataTransfer.getData('application/nest-files'));transfer(payload.sid,payload.paths)}catch{}}}><div className="file-table-head"><span>名称</span><span>类型</span><span>大小</span></div>{items.map(f=><div key={f.path} className={'file-row '+(d.selected.includes(f.path)?'selected':'')} data-testid="files-item" data-file-path={f.path} draggable onDragStart={e=>{if(!d.selected.includes(f.path))d.selected=[f.path];e.dataTransfer.setData('application/nest-files',JSON.stringify({sid:s.id,paths:d.selected}));e.dataTransfer.effectAllowed='copy'}} onClick={e=>{d.selected=e.ctrlKey?(d.selected.includes(f.path)?d.selected.filter(x=>x!==f.path):[...d.selected,f.path]):[f.path];engine.emit()}} onDoubleClick={()=>f.type==='folder'?navigate(f.path):engine.openFile(s.id,f.path)} onContextMenu={e=>{e.preventDefault();e.stopPropagation();d.selected=[f.path];setMenu({x:e.clientX-e.currentTarget.closest('.window-content').getBoundingClientRect().left,y:e.clientY-e.currentTarget.closest('.window-content').getBoundingClientRect().top});engine.emit()}}><span><span className={'file-type-icon '+colors[fileApp(f)]}><Icon app={fileApp(f)} size={22}/></span><b>{f.name}</b></span><span>{f.type==='folder'?'文件夹':f.path.split('.').pop().toUpperCase()+' 文件'}</span><span>{f.type==='folder'?'—':f.content.length>1024?(f.content.length/1024).toFixed(1)+' KB':f.content.length+' B'}</span></div>)}{items.length===0&&<div className="empty"><Folder size={42}/><h3>这里还很安静</h3><p>创建文件，或把另一层桌面的文件拖到这里。</p></div>}{dragging&&<div className="drop-label"><Copy/>复制到 {s.name} / {d.path}</div>}</div></div>
 <footer className="app-status"><span>{items.length} 个项目 {d.selected.length?'· 已选择 '+d.selected.length+' 项':''}</span><span>文件在各系统之间保持独立</span><button data-testid="files-open" disabled={!d.selected.length} onClick={()=>{const f=selected()[0];if(f)f.type==='folder'?navigate(f.path):engine.openFile(s.id,f.path)}}>打开所选 <ArrowUpRight size={13}/></button></footer>
 {menu&&<div className="context-menu" style={{left:menu.x,top:menu.y}} onMouseLeave={()=>setMenu(null)}>{[['copy','复制'],['cut','剪切'],['rename','重命名'],['delete','移到回收站'],...(d.path==='/Recycle'?[['restore','还原']]:[])].map(([a,label])=><button key={a} onClick={()=>act(a)}>{label}</button>)}</div>}
 {dialog&&<Dialog title={dialog.type==='overwrite'?'替换同名文件？':dialog==='rename'?'重命名':dialog==='folder'?'新建文件夹':'新建文件'} onClose={()=>setDialog(null)} actions={<><Button onClick={()=>setDialog(null)}>取消</Button><Button primary onClick={dialog.type==='overwrite'?dialog.execute:confirm}>{dialog.type==='overwrite'?'替换':'确定'}</Button></>}>{dialog.type==='overwrite'?<p>目标目录中已有同名文件，替换后原文件内容将更新。</p>:<input autoFocus className="text-input" value={name} aria-label="文件名" onChange={e=>setName(e.target.value)} onKeyDown={e=>{if(e.key==='Enter')confirm()}}/>}</Dialog>}
 </div>
}
function Sheet({w}){const d=w.data,s=engine.system(w.systemId);const [editing,setEditing]=useState(null),[value,setValue]=useState(''),[formula,setFormula]=useState(String(d.cells[d.selected]??''));const tableRef=useRef();const selection=parseRange(d.range||d.selected);useEffect(()=>setFormula(String(d.cells[d.selected]??'')),[d.selected,d.revision]);
 const select=(a,extend=false)=>{d.selected=a;if(extend){const from=(d.range||a).split(':')[0];d.range=from+':'+a}else d.range=a;engine.emit()};const commit=(cell,v)=>{engine.updateSheet(w,{[cell]:v});setEditing(null)};const save=()=>{const result=engine.writeFile(s.id,d.path,JSON.stringify({title:d.title,cells:d.cells,format:d.format}));if(!result.ok)return engine.notify(s.id,result.error);d.dirty=false;engine.notify(s.id,'工作簿已保存 · '+d.path)};
 const copied=()=>{const lines=[];for(let r=selection.r0;r<=selection.r1;r++){const row=[];for(let c=selection.c0;c<=selection.c1;c++)row.push(d.cells[address(r,c)]??'');lines.push(row.join('\t'))}const text=lines.join('\n');engine.state.clipboard.unshift(text);engine.state.clipboard=engine.state.clipboard.slice(0,20);navigator.clipboard?.writeText(text);engine.emit();return text};
 const paste=text=>{const[r,c]=parseCell(d.selected),changes={};text.replace(/\r/g,'').split('\n').forEach((line,y)=>line.split('\t').forEach((v,x)=>changes[address(r+y,c+x)]=v));engine.updateSheet(w,changes)};
 return<div className="sheet-app app-shell" onKeyDown={e=>{if(e.target.tagName==='INPUT')return;if((e.ctrlKey||e.metaKey)&&e.key==='z'){e.preventDefault();engine.undoSheet(w,e.shiftKey)}if((e.ctrlKey||e.metaKey)&&e.key==='y'){e.preventDefault();engine.undoSheet(w,true)}if((e.ctrlKey||e.metaKey)&&e.key==='s'){e.preventDefault();save()}if(e.key==='Delete'){let changes={};for(let r=selection.r0;r<=selection.r1;r++)for(let c=selection.c0;c<=selection.c1;c++)changes[address(r,c)]='';engine.updateSheet(w,changes)} }} onCopy={e=>{if(e.target.tagName==='INPUT')return;e.preventDefault();e.clipboardData.setData('text/plain',copied())}} onPaste={e=>{if(e.target.tagName==='INPUT')return;e.preventDefault();paste(e.clipboardData.getData('text/plain'))}} tabIndex={0}>
 <div className="sheet-heading"><div className="sheet-logo"><Table2 size={24}/></div><div><input className="document-title" data-testid="sheet-filename" aria-label="工作簿文件名" value={d.title} onChange={e=>{d.title=e.target.value;d.path='/Documents/'+e.target.value+'.sheet';d.dirty=true;engine.emit()}}/><span>{d.dirty?'尚未保存修改':'所有更改已保存'} · {d.path}</span></div><span className="spacer"/><span className="live-badge"><span className="status-dot"/>可连接实时图表</span><Button primary icon={Save} testId="sheet-save" onClick={save}>保存</Button></div>
 <div className="sheet-tabs"><b>开始</b><span>公式</span><span>数据</span><Button icon={Plus} onClick={()=>{const n=engine.open(s.id,'spreadsheet');n.data.cells={};n.data.values={};n.data.title='新建工作簿';n.data.path='/Documents/新建工作簿.sheet';engine.emit()}}>新建工作簿</Button></div>
 <div className="app-toolbar"><Mini icon={Undo2} label="撤销" onClick={()=>engine.undoSheet(w)}/><Mini icon={Redo2} label="重做" onClick={()=>engine.undoSheet(w,true)}/><i/><Button icon={Copy} onClick={copied}>复制</Button><Button icon={Clipboard} onClick={async()=>paste(await navigator.clipboard.readText())}>粘贴</Button><i/><Mini icon={Bold} label="加粗选区" onClick={()=>{d.format.bold=!(d.format.bold);d.dirty=true;engine.emit()}}/><span className="format-label">常规</span><span className="spacer"/><span className="toolbar-muted">数据版本 v{d.revision}</span></div>
 <div className="formula-bar"><span>{d.selected}</span><b>ƒx</b><input data-testid="sheet-formula" aria-label="公式编辑栏" value={formula} onChange={e=>setFormula(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'){commit(d.selected,formula);e.target.blur()}}} onBlur={()=>{if(formula!==String(d.cells[d.selected]??''))commit(d.selected,formula)}}/></div>
 <div className="sheet-scroll" ref={tableRef}><table className="sheet-grid" data-testid="sheet-grid"><thead><tr><th/><>{Array.from({length:12},(_,c)=><th key={c}>{String.fromCharCode(65+c)}</th>)}</></tr></thead><tbody>{Array.from({length:25},(_,r)=><tr key={r}><th>{r+1}</th>{Array.from({length:12},(_,c)=>{const a=address(r,c),sel=r>=selection.r0&&r<=selection.r1&&c>=selection.c0&&c<=selection.c1;return<td key={a} data-testid="sheet-cell" data-cell-address={a} tabIndex={0} aria-label={`${a} ${d.values[a]??''}`} className={`${sel?'selected':''} ${d.selected===a?'current':''} ${r===0&&d.format.header?'header-cell':''} ${typeof d.values[a]==='number'?'numeric':''} ${String(d.values[a]).startsWith('#')?'error-cell':''}`} style={{fontWeight:d.format.bold&&sel?700:undefined}} onMouseDown={e=>{if(editing!==a)select(a,e.shiftKey)}} onMouseEnter={e=>{if(e.buttons===1&&!editing){d.range=(d.range||a).split(':')[0]+':'+a;engine.emit()}}} onDoubleClick={()=>{setEditing(a);setValue(String(d.cells[a]??''))}} onKeyDown={e=>{if(editing)return;if(e.key==='Enter'){setEditing(a);setValue(String(d.cells[a]??''));e.preventDefault()}else if(e.key.length===1&&!e.ctrlKey){setEditing(a);setValue(e.key);e.preventDefault()}else if(['ArrowDown','ArrowUp','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const nr=r+(e.key==='ArrowDown'?1:e.key==='ArrowUp'?-1:0),nc=c+(e.key==='ArrowRight'?1:e.key==='ArrowLeft'?-1:0);if(nr>=0&&nc>=0){select(address(nr,nc),e.shiftKey);tableRef.current.querySelector(`[data-cell-address="${address(nr,nc)}"]`)?.focus()}}}}>{editing===a?<input autoFocus value={value} onChange={e=>setValue(e.target.value)} onBlur={()=>commit(a,value)} onKeyDown={e=>{e.stopPropagation();if(e.key==='Enter'){commit(a,value);select(address(r+1,c))}if(e.key==='Escape')setEditing(null)}}/>:d.values[a]??''}</td>})}</tr>)}</tbody></table></div>
 <div className="sheet-bottom"><Plus size={15}/><span>工作表 1 <ChevronDown size={12}/></span><span className="spacer"/><small>选区 {d.range}</small><small>求和 {Object.entries(d.values).filter(([a,v])=>{const[r,c]=parseCell(a);return typeof v==='number'&&r>=selection.r0&&r<=selection.r1&&c>=selection.c0&&c<=selection.c1}).reduce((n,[a,v])=>n+v,0)}</small><small>100%</small></div>
 </div>
}
function Editor({w}){const d=w.data,s=engine.system(w.systemId);const save=()=>engine.dispatch(w,{type:'editor-save'});const p=s.processes.find(p=>p.id===d.lastRunId);return<div className="editor-app app-shell"><div className="app-toolbar"><Button icon={Plus} onClick={()=>engine.open(s.id,'editor')}>新建</Button><Button icon={Save} testId="editor-save" onClick={save}>保存</Button><span className="spacer"/><Button primary icon={Play} onClick={()=>{engine.dispatch(w,{type:'editor-run'})}}>运行程序</Button></div><div className="editor-file"><Code2 size={16}/><input data-testid="editor-filename" aria-label="文件路径" value={d.path} onChange={e=>{d.path=e.target.value;d.dirty=true;engine.emit()}}/><span>{d.dirty?'● 未保存':'已保存'}</span></div><div className="editor-area"><div className="line-numbers">{d.text.split('\n').map((_,i)=><div key={i}>{i+1}</div>)}</div><textarea spellCheck={false} data-testid="editor-text" aria-label="程序与文本编辑器" value={d.text} onChange={e=>{d.text=e.target.value;d.dirty=true;engine.emit()}} onKeyDown={e=>{if(e.ctrlKey&&e.key==='s'){e.preventDefault();save()}if(e.key==='Tab'){e.preventDefault();const el=e.target,a=el.selectionStart;d.text=d.text.slice(0,a)+'  '+d.text.slice(el.selectionEnd);engine.emit();requestAnimationFrame(()=>el.selectionStart=el.selectionEnd=a+2)}}}/></div>{p?.display&&<ProgramDisplay process={p} systemId={s.id}/>} {p&&<div className="editor-console"><div><Terminal size={14}/> 输出 · {p.id} <span>{p.state}</span><Mini icon={X} label="关闭输出" onClick={()=>{d.lastRunId=null;engine.emit()}}/></div><pre>{p.output.join('\n')||'程序运行中…'}</pre><small>工作量 {p.work} · PC {p.pc} · {p.error}</small></div>}<footer className="app-status"><span>{s.id} / 独立文件系统</span><span>{d.path.endsWith('.nx')?'NEX 指令程序':'UTF-8 文本'} · {d.text.split('\n').length} 行</span></footer></div>}
function Browser({w}){const d=w.data;const refs=useRef({});const addressEditing=useRef(false);const[addr,setAddr]=useState(d.tabs[d.active]?.url||'');const tab=d.tabs[d.active];useEffect(()=>{if(!addressEditing.current)setAddr(tab?.url||'')},[tab?.id,tab?.url]);const add=url=>{d.tabs.push({id:engine.id('tab'),url:url||'https://www.bing.com',title:'新标签页',loadState:'idle'});d.active=d.tabs.length-1;engine.emit()};useEffect(()=>window.host?.onBrowserOpen(payload=>{const owns=Object.values(refs.current).some(v=>{try{return v?.getWebContentsId()===payload.guestId}catch{return false}});if(owns)add(payload.url)}),[]);const go=()=>{let url=addr.trim();if(!url)return;if(!/^https?:\/\//.test(url))url=url.includes('.')?'https://'+url:'https://www.bing.com/search?q='+encodeURIComponent(url);addressEditing.current=false;tab.url=url;tab.error='';tab.loadState='loading';if(tab.guestReady)refs.current[tab.id]?.loadURL(url).catch(()=>{});else tab.pendingUrl=url;engine.emit()};return<div className="browser-app app-shell"><div className="browser-tabs">{d.tabs.map((t,i)=><div key={t.id} className={'browser-tab '+(i===d.active?'active':'')} data-testid="browser-tab" data-tab-id={t.id} onClick={()=>{addressEditing.current=false;d.active=i;setAddr(d.tabs[i].url);engine.emit()}}><Globe size={14}/><span>{t.title||'新标签页'}</span><button data-testid="browser-close-tab" aria-label="关闭标签" onClick={e=>{e.stopPropagation();delete refs.current[t.id];d.tabs.splice(i,1);d.active=Math.min(d.active,d.tabs.length-1);if(!d.tabs.length)add();engine.emit()}}><X size={13}/></button></div>)}<Mini icon={Plus} label="新建标签" testId="browser-new-tab" onClick={()=>add()}/></div><div className="browser-navigation"><Mini icon={ArrowLeft} label="后退" testId="browser-back" onClick={()=>{const v=refs.current[tab.id];if(tab.guestReady&&v?.canGoBack())v.goBack()}}/><Mini icon={MoveRight} label="前进" testId="browser-forward" onClick={()=>{const v=refs.current[tab.id];if(tab.guestReady&&v?.canGoForward())v.goForward()}}/><Mini icon={tab?.loadState==='loading'?X:RefreshCw} label="刷新或停止" testId="browser-reload" onClick={()=>tab.loadState==='loading'?refs.current[tab.id]?.stop():refs.current[tab.id]?.reload()}/><div className="browser-address"><Globe size={15}/><input data-testid="browser-address" aria-label="输入网址或搜索" value={addr} onChange={e=>{addressEditing.current=true;setAddr(e.target.value)}} onKeyDown={e=>{if(e.key==='Enter')go()}} onFocus={e=>{addressEditing.current=true;e.target.select()}}/><button data-testid="browser-go" aria-label="访问网址" onClick={go}><ArrowUpRight size={16}/></button></div><span className="chromium-label">Chromium</span></div><div className="browser-bookmarks"><button onClick={()=>{setAddr('https://www.bilibili.com');tab.url='https://www.bilibili.com';refs.current[tab.id]?.loadURL(tab.url)}}>哔哩哔哩</button><button onClick={()=>refs.current[tab.id]?.loadURL('https://www.wikipedia.org')}>Wikipedia</button><button onClick={()=>refs.current[tab.id]?.loadURL('https://www.bing.com')}>Bing</button><span className="spacer"/><span>{tab?.loadState==='loading'?'正在连接网络…':tab?.loadState==='error'?'加载失败，可刷新重试':'真实网页 · 独立浏览设备'}</span></div><div className="webviews">{d.tabs.map((t,i)=><WebTab key={t.id} tab={t} visible={d.active===i} onRef={el=>refs.current[t.id]=el}/>)}</div></div>}
function WebTab({tab,visible,onRef}){const ref=useRef();const initial=useRef(tab.url);useEffect(()=>{const v=ref.current;onRef(v);tab.guestReady=false;const ready=()=>{tab.guestReady=true;if(tab.pendingUrl){const url=tab.pendingUrl;tab.pendingUrl=null;v.loadURL(url).catch(()=>{})}engine.emit()};v.addEventListener('dom-ready',ready);const start=()=>{tab.loadState='loading';engine.emit()},stop=()=>{if(tab.loadState!=='error')tab.loadState='loaded';engine.emit()},nav=e=>{tab.url=e.url;engine.emit()},title=e=>{tab.title=e.title;engine.emit()},fail=e=>{if(e.errorCode===-3)return;tab.loadState='error';tab.error=e.errorDescription;engine.emit()};v.addEventListener('did-start-loading',start);v.addEventListener('did-stop-loading',stop);v.addEventListener('did-navigate',nav);v.addEventListener('did-navigate-in-page',nav);v.addEventListener('page-title-updated',title);v.addEventListener('did-fail-load',fail);return()=>{v.removeEventListener('dom-ready',ready);v.removeEventListener('did-start-loading',start);v.removeEventListener('did-stop-loading',stop);v.removeEventListener('did-navigate',nav);v.removeEventListener('did-navigate-in-page',nav);v.removeEventListener('page-title-updated',title);v.removeEventListener('did-fail-load',fail)}},[]);return<div className="webtab" style={{display:visible?'flex':'none'}}><webview ref={ref} src={initial.current} allowpopups="true" webpreferences="contextIsolation=yes,nodeIntegration=no,sandbox=yes,backgroundThrottling=no"/>{tab.loadState==='error'&&<div className="browser-error"><Globe size={40}/><h3>暂时无法访问这个页面</h3><p>{tab.error}</p><Button onClick={()=>ref.current.reload()}>重新加载</Button></div>}</div>}
function Systems({w}){const s=engine.system(w.systemId);const children=engine.children(s.id);const tree=(id,depth=0)=>{const n=engine.system(id);return<div key={id}><div className={'tree-node '+(id===s.id?'active':'')} style={{paddingLeft:14+depth*18}}><Layers size={15}/><b>{id}</b><span className={'status-dot '+n.state}/></div>{engine.children(id).map(c=>tree(c.id,depth+1))}</div>};return<div className="systems-app app-shell"><div className="page-heading"><div><span className="eyebrow">SYSTEM EXPLORER</span><h2>系统空间</h2><p>独立运行，层层相连。</p></div><Button primary icon={Plus} testId="system-new" onClick={()=>engine.createChild(s.id)}>新建子系统</Button></div><div className="system-layout"><aside className="system-tree"><div className="section-caption">系统拓扑</div>{tree('outer')}<div className="tree-note"><Layers size={30}/><p>每一个系统，都可以<br/>成为另一个世界的起点。</p></div></aside><div className="system-cards"><div className="system-current"><div className="icon-tile teal"><Monitor/></div><div><b>{s.name}</b><span>当前桌面 · {s.parentId?'父级 '+s.parentId:'根系统'}</span></div><div className="system-stat"><b>{s.time.toFixed(1)}<small>s</small></b><span>虚拟时间</span></div><div className="system-stat"><b>{children.length}</b><span>直属子系统</span></div></div><div className="section-caption">直属子系统 <span>单步长度 50 ms</span></div>{children.length===0?<div className="empty system-empty"><Layers size={48}/><h3>下一层，由你开启</h3><p>新的桌面拥有独立的文件、进程与虚拟时间。<br/>在这里开始飞行，连接数据，探索层层嵌套。</p><Button icon={Plus} primary onClick={()=>engine.createChild(s.id)}>创建第一个子系统</Button></div>:children.map(c=><div className="system-card" key={c.id}><div className="system-card-heading"><span className="icon-tile lavender"><Layers/></span><div><h3>{c.name}</h3><p>{s.name} <ChevronRight size={12}/> {c.name} · 第 {engine.ancestors(c.id).length+1} 层</p></div><span className={'state-badge '+c.state}><i/>{({running:'运行中',paused:'已暂停',stopped:'已停止',error:'内核错误'})[c.state]}</span><Mini icon={ArrowUpRight} label="打开子系统桌面" onClick={()=>{const win=s.windows.find(x=>x.appId==='system'&&x.data.childId===c.id);if(win){win.state='normal';engine.focus(win)}else engine.open(s.id,'system',{childId:c.id})}}/></div><div className="system-card-data"><span>虚拟时钟 <b>{c.time.toFixed(2)} s</b></span><span>实际拨付 <b>{c.actual} / {c.budget}</b></span><span>进程 <b>{c.processes.filter(p=>p.state!=='ended').length}</b></span></div>{c.state==='error'&&<div className="error-banner" data-testid="kernel-error">{c.error||c.kernel.error}</div>}<div className="system-controls"><Button icon={Pause} testId="system-pause" data-target-system-id={c.id} onClick={()=>engine.pause(c.id)}>暂停</Button><Button icon={Play} testId="system-resume" data-target-system-id={c.id} onClick={()=>engine.resume(c.id)}>继续</Button><Mini icon={SkipForward} label="单步 50 毫秒" onClick={()=>engine.step(c.id)}/><label className="inline-label">速率<select aria-label={`${c.id} 时间速率`} value={c.rate} onChange={e=>{c.rate=+e.target.value;engine.emit()}}>{[.25,.5,1,2,4].map(r=><option key={r} value={r}>{r}×</option>)}</select></label><span className="spacer"/><Mini icon={Camera} label="创建快照" onClick={()=>engine.capture(c.id)}/><Mini icon={RotateCcw} label="恢复快照" onClick={()=>engine.restore(c.id)}/><Mini icon={GitBranch} label="从快照分叉" onClick={()=>engine.restore(c.id,true)}/><Mini icon={Code2} label="打开内核源文件" testId="kernel-open" data-target-system-id={c.id} onClick={()=>engine.open(s.id,'editor',{path:c.kernelPath})}/><Mini icon={RefreshCw} label="重新载入内核并重启" testId="system-restart" data-target-system-id={c.id} onClick={()=>engine.restart(c.id)}/><Mini icon={Square} label="停止子树" onClick={()=>engine.stop(c.id)}/></div></div>)}<div className="section-caption">已保存快照</div>{engine.state.snapshots.filter(x=>x.parentId===s.id).map(x=><div className="snapshot-row" key={x.id}><Camera size={17}/><span>{x.path.split('/').pop()}<small>{x.status==='saving'?'正在按预算写入 · ':''}保存时钟 {x.time.toFixed(2)} s</small></span><Button disabled={!s.files[x.path]} onClick={()=>engine.restoreFile(s.id,JSON.parse(s.files[x.path].content),false)}>恢复</Button><Button disabled={!s.files[x.path]} onClick={()=>engine.restoreFile(s.id,JSON.parse(s.files[x.path].content),true)}>分叉</Button></div>)}</div></div></div>}
function Tasks({w}){const s=engine.system(w.systemId);const [selected,setSelected]=useState(null);const p=s.processes.find(p=>p.id===selected);const memory=engine.memoryUsed(s),storage=engine.storageUsed(s);return<div className="tasks-app app-shell"><div className="page-heading compact"><div><span className="eyebrow">RESOURCE MONITOR</span><h2>任务管理器</h2></div><span className="live-badge"><span className="status-dot"/>{s.name} · {s.time.toFixed(2)} s</span></div><div className="resource-metrics"><div><span>执行预算 / 逻辑步</span><b>{s.actual.toLocaleString()}<small> / {s.budget.toLocaleString()}</small></b><div className="meter"><i style={{width:s.actual/s.budget*100+'%'}}/></div><input data-testid="tasks-budget" aria-label="系统总预算" type="number" min="0" step="500" value={s.budget} onChange={e=>{s.budget=Math.max(0,+e.target.value);engine.emit()}}/></div><div><span>内核 / 用户工作</span><b>{s.kernelWork}<small> / {s.userWork}</small></b><small>按实际执行与服务规模计费</small></div><div><span>内存占用</span><b>{(memory/1024).toFixed(0)}<small> KB</small></b><label>额度 MB <input data-testid="tasks-memory" aria-label="内存额度 MB" type="number" value={s.memoryLimit/1048576} onChange={e=>{s.memoryLimit=+e.target.value*1048576;engine.emit()}}/></label></div><div><span>文件存储</span><b>{(storage/1024).toFixed(0)}<small> KB</small></b><label>额度 MB <input data-testid="tasks-storage" aria-label="存储额度 MB" type="number" value={s.storageLimit/1048576} onChange={e=>{s.storageLimit=+e.target.value*1048576;engine.emit()}}/></label></div></div><div className="app-toolbar"><Button icon={Pause} disabled={!p} onClick={()=>{p.state='suspended';if(p.role==='carrier')engine.pause(p.childId);engine.emit()}}>挂起进程</Button><Button icon={Play} disabled={!p} onClick={()=>{p.state='ready';if(p.role==='carrier')engine.resume(p.childId);engine.emit()}}>继续</Button><Button icon={Square} disabled={!p} onClick={()=>{if(p.windowId){const win=engine.getWindow(p.windowId);if(win)engine.close(win)}else engine.endProcess(s.id,p.id);engine.emit()}}>结束进程</Button><span className="spacer"/><small>{s.processes.length} 个逻辑进程</small></div><div className="process-scroll"><table className="process-table"><thead><tr><th>名称 / 进程身份</th><th>状态</th><th>累计工作</th><th>本步</th><th>等待 / 剩余</th><th>上限</th></tr></thead><tbody>{s.processes.map(p=><tr key={p.id} className={selected===p.id?'selected':''} onClick={()=>setSelected(p.id)}><td><b>{p.role==='carrier'?<Layers size={15}/>:<Activity size={15}/>} {p.name}</b><small>{p.id} {p.role==='carrier'?`· 内核 ${p.kernelWork||0} / 内部 ${p.childWork||0}`:''}</small></td><td><span className={'process-state '+p.state}>{({compiling:'编译中',ready:'就绪',waiting:'等待',suspended:'挂起',ended:'已结束',error:'异常'})[p.state]||p.state}</span></td><td>{p.work.toLocaleString()}</td><td>{p.lastWork}</td><td>{p.pending?Math.max(0,p.pending.cost-p.pending.progress)+' 单位':p.queue.length?p.queue.length+' 条消息':p.wake>s.time?(p.wake-s.time).toFixed(2)+' s':'—'}</td><td><input type="number" aria-label={p.name+' 额度'} value={p.role==='carrier'?engine.system(p.childId)?.grant:p.cap} data-testid={p.role==='carrier'?'tasks-grant':undefined} data-target-system-id={p.childId} onChange={e=>{p.cap=Math.max(0,+e.target.value);if(p.childId)engine.system(p.childId).grant=p.cap;engine.emit()}}/></td></tr>)}</tbody></table>{s.windows.filter(w=>w.appId==='browser').map(w=><div className="browser-device" key={w.id}><Globe size={16}/>Chromium 浏览器设备 · {w.data.tabs.length} 个网页视图 <span>独立宿主工作，不计入逻辑指令预算</span></div>)}</div>{p&&<div className="process-details"><span><b>{p.id}</b> · PC {p.pc} · 内存 {p.memory} B</span><code>{p.error||p.output.slice(-3).join(' / ')||JSON.stringify(p.vars).slice(0,600)}</code></div>}<footer className="app-status"><span>父层实际拨付限制本层总预算 · 速率不会增加额度</span><span>逻辑步 50 ms</span></footer></div>}
function Preferences({w}){const s=engine.system(w.systemId);return<div className="preferences-app app-shell"><div className="page-heading"><div><span className="eyebrow">MAKE IT YOURS</span><h2>把桌面，变成你的样子。</h2><p>每一层，都可以有自己的个性。</p></div><Settings size={36}/></div><div className="preferences-scroll"><div className="setting-row"><div><h3>工作空间名称</h3><p>在桌面、系统空间和通知中显示</p></div><input className="text-input" aria-label="系统名称" value={s.name} onChange={e=>{s.name=e.target.value;engine.emit()}}/></div><div className="settings-section"><h3>桌面壁纸</h3><div className="wallpaper-options">{[['landscape','山湖之间'],['aurora','薄荷极光'],['dusk','暮色山峦']].map(([v,title])=><button className={s.settings.wallpaper===v?'selected':''} key={v} data-testid="settings-wallpaper" data-value={v} onClick={()=>{s.settings.wallpaper=v;engine.emit()}}><span className={'wallpaper-preview '+v}>{s.settings.wallpaper===v&&<CheckCircle2 size={20}/>}</span><b>{title}</b></button>)}</div></div><div className="setting-row"><div><h3>强调色</h3><p>让按钮、焦点与选区使用同一种色彩</p></div><div className="accent-options">{['#337f79','#7665a3','#427ca8','#b57548','#ba5c72','#414e5e'].map(color=><button aria-label={'强调色 '+color} data-testid="settings-accent" data-value={color} key={color} style={{background:color}} onClick={()=>{s.settings.accent=color;engine.emit()}}>{s.settings.accent===color&&<Check size={17}/>}</button>)}</div></div><div className="setting-row"><div><h3>界面缩放</h3><p>文字与控件随显示比例调整</p></div><select data-testid="settings-scale" aria-label="界面缩放" value={s.settings.scale} onChange={e=>{s.settings.scale=+e.target.value;engine.emit()}}>{[85,100,110,125,150].map(v=><option key={v} value={v} data-value={v}>{v}%{v===100?' · 默认':''}</option>)}</select></div><div className="setting-row"><div><h3>免打扰</h3><p>保留通知记录，暂时不显示弹出提示</p></div><button className={'toggle '+(s.settings.dnd?'on':'')} aria-label="免打扰" onClick={()=>{s.settings.dnd=!s.settings.dnd;engine.emit()}}><i/></button></div><div className="settings-about"><div className="brandmark"><Layers/></div><div><b>层界 NEST</b><p>一个工作空间，无限层可能。</p></div><span>VERSION 1.0<br/>独立递归桌面</span></div></div></div>}
function Widgets({w}){const s=engine.system(w.systemId),g=s.widgets;const[month,setMonth]=useState(new Date(new Date(s.epoch||Date.now()).getFullYear(),new Date(s.epoch||Date.now()).getMonth(),1));const date=new Date((s.epoch||Date.now())+s.time*1000);const dayCount=new Date(month.getFullYear(),month.getMonth()+1,0).getDate(),offset=new Date(month.getFullYear(),month.getMonth(),1).getDay();return<div className="widgets-app app-shell"><div className="page-heading compact"><div><span className="eyebrow">A MOMENT FOR YOURSELF</span><h2>今天，也从容一点。</h2></div><span className="date-label">{date.toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</span></div><div className="widget-grid"><div className="widget-card calendar-card"><div className="widget-title"><Calendar size={17}/>时钟与日历</div><div className="big-clock">{date.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}<small>{String(date.getSeconds()).padStart(2,'0')}</small></div><div className="calendar-heading"><b>{month.getFullYear()} 年 {month.getMonth()+1} 月</b><span><Mini icon={ChevronLeft} label="上个月" onClick={()=>setMonth(new Date(month.getFullYear(),month.getMonth()-1,1))}/><Mini icon={ChevronRight} label="下个月" onClick={()=>setMonth(new Date(month.getFullYear(),month.getMonth()+1,1))}/></span></div><div className="calendar-grid">{'日一二三四五六'.split('').map(x=><small key={x}>{x}</small>)}{Array.from({length:offset},(_,i)=><span key={'empty'+i}/>)}{Array.from({length:dayCount},(_,i)=><button key={i} className={month.getMonth()===date.getMonth()&&i+1===date.getDate()?'today':''}>{i+1}</button>)}</div></div><div className="widget-card timer-card"><div className="widget-title"><Timer size={17}/>专注计时</div><div className="timer-display">{fmtTime(g.timer)}</div><label className="timer-setting">倒计时秒数<input data-testid="widget-timer-input" aria-label="倒计时秒数" type="number" value={g.timerInitial} onChange={e=>{g.timerInitial=+e.target.value;if(!g.timerRunning)g.timer=+e.target.value;engine.emit()}}/></label><div className="widget-buttons"><Button primary icon={Play} testId="widget-timer-start" onClick={()=>{g.timerRunning=true;engine.emit()}}>开始</Button><Mini icon={Pause} label="暂停计时" testId="widget-timer-pause" onClick={()=>{g.timerRunning=false;engine.emit()}}/><Mini icon={RotateCcw} label="重置计时" testId="widget-timer-reset" onClick={()=>{g.timerRunning=false;g.timer=g.timerInitial;engine.emit()}}/></div><hr/><div className="stopwatch"><span>秒表 <b>{fmtTime(g.stopwatch)}.{String(Math.floor(g.stopwatch%1*100)).padStart(2,'0')}</b></span><div><Mini icon={g.stopwatchRunning?Pause:Play} label="开始或暂停秒表" onClick={()=>{g.stopwatchRunning=!g.stopwatchRunning;engine.emit()}}/><Mini icon={Plus} label="记录分段" onClick={()=>{g.laps.push(g.stopwatch);engine.emit()}}/><Mini icon={RotateCcw} label="复位秒表" onClick={()=>{g.stopwatch=0;g.laps=[];g.stopwatchRunning=false;engine.emit()}}/></div></div>{g.laps.slice(-3).map((t,i)=><small key={i}>分段 {i+1} · {t.toFixed(2)} s　</small>)}</div><div className="widget-card note-card"><div className="widget-title"><StickyNote size={17}/>随手记<span className="spacer"/><Mini icon={Plus} label="新增便笺" onClick={()=>{g.notes.push({id:Date.now(),text:''});engine.emit()}}/></div>{g.notes.map(n=><div className="note-item" key={n.id}><textarea data-testid="widget-note-text" aria-label="便笺内容" value={n.text} onChange={e=>{n.text=e.target.value;engine.emit()}}/><div><small>你的想法，值得留下。</small><Mini icon={Trash2} label="删除便笺" onClick={()=>{g.notes=g.notes.filter(x=>x.id!==n.id);engine.emit()}}/></div></div>)}<Button icon={Check} testId="widget-note-save" onClick={()=>engine.notify(s.id,'便笺已保存')}>保存便笺</Button></div><div className="widget-card clipboard-card"><div className="widget-title"><Clipboard size={17}/>剪贴板历史<span className="spacer"/><Mini icon={Trash2} label="清空剪贴板历史" onClick={()=>{engine.state.clipboard=[];engine.emit()}}/></div><div data-testid="widget-clipboard-list">{engine.state.clipboard.length?engine.state.clipboard.map((t,i)=><button className="clipboard-item" key={i} onClick={()=>navigator.clipboard.writeText(t)}><pre>{t.slice(0,160)}</pre><Copy size={14}/></button>):<div className="widget-empty"><Copy size={26}/><p>在表格中复制内容，<br/>就会出现在这里。</p></div>}</div></div><div className="widget-card notifications-card" data-testid="widget-notifications"><div className="widget-title"><Bell size={17}/>通知中心<span className="spacer"/><button className="text-button" onClick={()=>{s.notifications.forEach(n=>n.read=true);engine.emit()}}>全部已读</button><Mini icon={Trash2} label="清除通知" onClick={()=>{s.notifications=[];engine.emit()}}/></div>{s.notifications.length?s.notifications.map(n=><div className={'notice-item '+(n.read?'read':'')} key={n.id} onClick={()=>{n.read=true;engine.emit()}}><span className="notice-icon"><Check size={15}/></span><span>{n.text}<small>{fmtTime(n.time)} · {s.name}</small></span>{!n.read&&<i className="status-dot"/>}</div>):<div className="widget-empty"><CheckCircle2 size={28}/><p>没有新通知。享受这份宁静。</p></div>}</div><div className="widget-card quick-settings"><div className="widget-title"><Settings size={17}/>快捷设置</div><div className="quick-buttons"><button onClick={()=>{s.settings.wallpaper=s.settings.wallpaper==='dusk'?'landscape':'dusk';engine.emit()}}><Moon size={20}/>切换主题</button><button className={s.settings.dnd?'selected':''} onClick={()=>{s.settings.dnd=!s.settings.dnd;engine.emit()}}><Bell size={20}/>免打扰</button><button onClick={()=>engine.open(s.id,'settings')}><Settings size={20}/>全部设置</button></div><label>界面缩放 <select value={s.settings.scale} onChange={e=>{s.settings.scale=+e.target.value;engine.emit()}}>{[85,100,110,125,150].map(v=><option key={v}>{v}</option>)}</select></label></div></div></div>}
function Player({w,control=w}){const d=w.data,s=engine.system(w.systemId);const [panel,setPanel]=useState(false);const blocked=!!engine.blockedReason(w.systemId);const cmd=(action,value)=>engine.dispatch(control,{type:'player',action,value});const scenePaths=Object.keys(s.files).filter(p=>p.endsWith('.scene')||p.endsWith('.flight'));const phase=d.mode==='rehearsal'?(d.physics.crashed?'接触 / 已记录':'闭环飞行'):(d.resource.phases?.filter(p=>p.time<=d.position).at(-1)?.title||d.resource.title||'场景预览');return<div className="player-app app-shell"><div className="player-top"><div className="player-project"><span className="scene-emblem">{d.resource.badge||"3D"}</span><div><b>{d.resource.title||'三维场景'}</b><small>{d.mode==='rehearsal'?'FLIGHT REHEARSAL':d.resource.subtitle||'SCENE RESOURCE'}</small></div></div><span className="spacer"/><select aria-label="打开场景文件" data-testid="player-open" value={d.scene} disabled={blocked} onChange={e=>cmd('load',e.target.value)}>{scenePaths.map(p=><option key={p} value={p}>{p.split('/').pop()}</option>)}</select><Mini icon={Settings} label="飞行排演设置" onClick={()=>setPanel(!panel)}/></div><div className="player-scene-layout"><div className="scene-stage"><SceneView data={d} windowId={control.id} blocked={blocked} onAction={cmd}/><div className="scene-top-left"><span className="scene-mode"><i/>{d.mode==='rehearsal'?'实时排演':'场景预览'} <span>WEBGL 2</span></span><h3>{phase}</h3><p>{d.resource.description||"交互式三维场景"}</p></div><div className="scene-top-right"><select data-testid="player-camera" aria-label="相机模式" value={d.camera} disabled={blocked} onChange={e=>cmd('camera',e.target.value)}><option value="cinematic">演出镜头</option><option value="follow">跟随镜头</option><option value="orbit">自由环绕</option></select></div><div className="scene-bottom-left"><span>ALT <b>{(d.frame.pose?.y||0).toFixed(1)} <small>m</small></b></span><span>HDG <b>{((d.frame.pose?.yaw||0)*180/Math.PI%360).toFixed(0)}<small>°</small></b></span><span>FRAME <b>{Math.round(d.frameTime*30).toString().padStart(3,'0')}</b></span></div><div className="scene-bottom-right" data-testid="player-selection">{d.selection||'拖动环绕 · 滚轮缩放 · 点选部件'}</div>{blocked&&<div className="scene-pause-banner"><Pause size={18}/>{engine.blockedReason(w.systemId)}</div>}</div>{panel&&<aside className="flight-panel"><div className="section-caption">飞行排演</div><p>从当前状态接管飞行，<br/>让调度参与每一次控制。</p><Button primary icon={Play} testId="rehearsal-start" disabled={blocked} onClick={()=>cmd('rehearsal')}>开始排演</Button><label><Wind size={15}/> 风力 <b>{d.wind}</b><input data-testid="rehearsal-wind" aria-label="风力" type="range" min="-15" max="15" value={d.wind} onChange={e=>cmd('wind',e.target.value)}/></label><label><Navigation size={15}/> 目标航向<input data-testid="rehearsal-heading" aria-label="目标航向弧度" type="number" step="0.2" value={d.heading} onChange={e=>cmd('heading',e.target.value)}/></label><Button icon={Target} onClick={()=>cmd('target',{x:14,z:-9,land:true})}>降落第二停机坪</Button><Button icon={AlertTriangle} testId="rehearsal-fault" onClick={()=>cmd('fault')}>触发旋翼故障</Button><Button icon={Code2} testId="rehearsal-controller" onClick={()=>engine.open(s.id,'editor',{path:'/Programs/flight-control.nx',controllerFor:w.id})}>编辑飞控程序</Button><Button icon={Save} onClick={()=>cmd('save-record')}>保存排演记录</Button><small>控制更新时间<br/>{d.control?.stamp?.toFixed(2)} s</small></aside>}</div><div className="player-timeline"><div className="timeline-chapters">{(d.resource.phases||[{title:"开始",time:0},{title:"结束",time:d.duration}]).map((p,i)=><span key={i}>{String(i+1).padStart(2,"0")} {p.title}</span>)}</div><input type="range" min="0" max={d.duration} step="0.033333" value={d.position} data-testid="player-seek" aria-label="播放进度" disabled={blocked} onChange={e=>cmd('seek',e.target.value)}/><div className="player-transport"><button className="play-circle" data-testid="player-play" aria-label="播放" disabled={blocked} onClick={()=>cmd('play')}><Play size={18} fill="currentColor"/></button><Mini icon={Pause} label="暂停" testId="player-pause" disabled={blocked} onClick={()=>cmd('pause')}/><Mini icon={Square} label="停止并回到开头" testId="player-stop" disabled={blocked} onClick={()=>cmd('stop')}/><Mini icon={SkipForward} label="前进一帧" testId="player-step" disabled={blocked} onClick={()=>cmd('step')}/><span className="player-time" data-testid="player-time"><input aria-label="跳转到时间秒" type="number" min="0" max={d.duration} step="0.1" disabled={blocked} value={+d.position.toFixed(2)} onChange={e=>cmd('seek',e.target.value)}/> <small>/ {d.duration.toFixed(2)} s</small></span><span className="spacer"/><span className="play-state"><span className={'status-dot '+(d.state==='playing'?'running':'paused')}/>{d.state==='playing'?'播放中':'已暂停'}</span><select data-testid="player-rate" aria-label="播放速率" disabled={blocked} value={d.rate} onChange={e=>cmd('rate',e.target.value)}>{[.25,.5,1,1.5,2,4].map(v=><option key={v} value={v}>{v}×</option>)}</select><button className={'mini '+(d.loop?'active':'')} data-testid="player-loop" aria-label="循环播放" disabled={blocked} onClick={()=>cmd('loop')}><Repeat size={17}/></button></div></div><footer className="app-status"><span>{s.id} · 三进程协作 · 30 FPS 取样</span><span>画面时刻 {d.frameTime.toFixed(3)} s</span></footer></div>}
function Charts({w,control=w}){const d=w.data;const sources=engine.system('outer').windows.filter(w=>w.appId==='spreadsheet');const blocked=!!engine.blockedReason(w.systemId);const edit=(key,value)=>engine.dispatch(control,{type:'chart',key,value});const [hover,setHover]=useState(null);const table=d.layout||[],header=table[0]||[],rows=table.slice(1);let region;try{region=parseRange(d.range)}catch{region={c0:0}}const label=Math.max(0,d.labelColumn.toUpperCase().charCodeAt(0)-65-region.c0);const series=d.series.toUpperCase().split(',').map(x=>x.trim().charCodeAt(0)-65-region.c0).filter(x=>x>=0&&x<header.length);const values=rows.flatMap(r=>series.map(c=>+r[c]||0));const max=d.plot?.high||Math.max(10,...values)*1.18,min=d.plot?.low||0,span=max-min;const colors=['#428c85','#a594c4','#dfa86e','#6a99b2'];const vw=660,vh=290,left=54,top=22,pw=580,ph=205;const group=pw/(rows.length||1);const conn={connected:'实时连接',disconnected:'未连接',restored:'已恢复，待重新连接','source-closed':'数据源已关闭'}[d.connectionState]||d.connectionState;return<div className="charts-app app-shell"><div className="chart-heading"><div><span className="eyebrow">DATA, IN A DIFFERENT DIMENSION</span><h2>让数据，跨越层级。</h2></div><span className={'connection-badge '+(d.connectionState==='connected'?'on':'')}><i/>{conn}</span></div><div className="chart-connect-panel"><label>根系统工作簿<select data-testid="chart-source" aria-label="数据源工作簿" disabled={blocked} value={d.sourceId} onChange={e=>edit('sourceId',e.target.value)}><option value="">选择已打开的工作簿</option>{sources.map(x=><option key={x.id} value={x.id}>{x.data.title}</option>)}</select></label><label>数据区域<input data-testid="chart-range" aria-label="数据选区" disabled={blocked} value={d.range} onChange={e=>edit('range',e.target.value)}/></label><label>标签列<input data-testid="chart-label-column" aria-label="标签列" disabled={blocked} value={d.labelColumn} onChange={e=>edit('labelColumn',e.target.value)}/></label><label>数值列<input data-testid="chart-series" aria-label="数值列，逗号分隔" disabled={blocked} value={d.series} onChange={e=>edit('series',e.target.value)}/></label><Button primary icon={Link2} testId="chart-connect" disabled={blocked} onClick={()=>engine.dispatch(control,{type:'connect',sourceId:d.sourceId,range:d.range,labelColumn:d.labelColumn,series:d.series})}>连接</Button><Mini icon={Unlink} label="断开数据连接" testId="chart-disconnect" disabled={blocked} onClick={()=>engine.dispatch(control,{type:'disconnect'})}/></div><div className="chart-body"><div className="chart-title"><div><input aria-label="图表标题" disabled={blocked} value={d.title} onChange={e=>edit('title',e.target.value)}/><span>{d.sourceTitle} · {d.range}</span></div><select data-testid="chart-type" aria-label="图表类型" disabled={blocked} value={d.chartType} onChange={e=>edit('chartType',e.target.value)}><option value="bar">分组柱状图</option><option value="line">折线图</option></select></div>{rows.length?<><div className="chart-legend">{series.map((c,i)=><span key={c}><i style={{background:colors[i%4]}}/>{header[c]||String.fromCharCode(c+65)}</span>)}<span className="spacer"/><span className="chart-revision">VERSION {String(d.version).padStart(3,'0')}</span></div><div className="chart-svg-container"><svg viewBox={`0 0 ${vw} ${vh}`} role="img" aria-label={d.title}><text x="18" y="15" className="axis-title">数值</text>{Array.from({length:5},(_,i)=>{const y=top+ph*i/4;return<g key={i}><line x1={left} y1={y} x2={left+pw} y2={y} stroke="#e5e9e7" strokeDasharray="3 5"/><text x={left-10} y={y+4} textAnchor="end">{Math.round(min+span*(1-i/4))}</text></g>})}{rows.map((r,ri)=><g key={ri}><text x={left+group*(ri+.5)} y={top+ph+27} textAnchor="middle">{r[label]}</text>{series.map((c,ci)=>{const val=+r[c]||0,bw=Math.min(62,group*.65/(series.length||1));const x=left+group*(ri+.5)+(ci-(series.length-1)/2)*bw*1.12;const y=top+ph-((val-min)/span)*ph,zero=top+ph-((0-min)/span)*ph;return<g key={ci} onMouseEnter={()=>setHover({label:r[label],series:header[c],value:val})} onMouseLeave={()=>setHover(null)} onClick={()=>{edit('selection',{label:r[label],series:header[c],value:val});setHover({label:r[label],series:header[c],value:val})}}>{d.chartType==='bar'?<rect x={x-bw/2} y={Math.min(y,zero)} width={bw} height={Math.abs(val/span*ph)} rx="4" fill={colors[ci%4]}/>:<circle cx={left+group*(ri+.5)} cy={y} r="5" fill={colors[ci%4]} stroke="white" strokeWidth="2"/>}<text x={d.chartType==='bar'?x:left+group*(ri+.5)} y={y-10} textAnchor="middle" className="value-label">{val}</text></g>})}</g>)}{d.chartType==='line'&&series.map((c,ci)=><path key={ci} d={rows.map((r,i)=>`${i?'L':'M'}${left+group*(i+.5)},${top+ph-(((+r[c]||0)-min)/span)*ph}`).join(' ')} fill="none" stroke={colors[ci%4]} strokeWidth="2.5"/>)}<text x={left+pw} y={vh-12} textAnchor="end" className="axis-title">{header[label]||'项目'}</text></svg>{(hover||d.selection)&&<div className="chart-tooltip"><b>{(hover||d.selection).label}</b> · {(hover||d.selection).series} <strong>{(hover||d.selection).value}</strong></div>}</div></>:<div className="chart-empty"><div className="empty-bars"><i/><i/><i/><i/><i/></div><h3>连接数据，发现新的视角</h3><p>在根桌面打开电子表格，选择工作簿与选区。<br/>每次编辑，都会把完整的数据版本传递到这里。</p></div>}</div><footer className="app-status"><span><span className="status-dot"/> {w.systemId} · 接收与绘制独立调度</span><span>{blocked?engine.blockedReason(w.systemId):rows.length?`${rows.length} 个项目 · ${series.length} 组数据`:'等待数据源'}</span></footer></div>}
function Help({w}){return<div className="help-app app-shell"><div className="page-heading"><div><span className="eyebrow">WELCOME TO NEST</span><h2>每一层，皆有新境。</h2><p>层界 NEST · 操作指南与程序接口</p></div><BookOpen size={40}/></div><div className="help-body"><h3>从桌面开始</h3><p>单击选择图标，双击打开应用。左下角开始菜单可以搜索所有工具。拖动标题栏移动窗口；右下角调整大小；双击标题栏最大化。拖到桌面左右边缘可半屏贴靠，任务栏可收起与恢复窗口。</p><h3>一条探索路线</h3><ol><li>在根系统打开「电子表格」，示例工作簿包含 A1:D4，双击 B2 修改数量。</li><li>点击「启动子系统」，在新桌面打开「图表工作台」，选择根系统工作簿、A1:D4、标签 A 与数值 B,D，点击连接。</li><li>在图表标题栏点击「投送」，选择 outer。根桌面中的投送控件会通过消息交给源应用。</li><li>在文件管理器中把 helicopter-24.scene 拖到更深层的文件列表。双击场景打开播放器，投送回根桌面，点击播放。</li></ol><h3>系统树、时间与资源</h3><p>「系统空间」管理直属子系统：暂停、继续、50 ms 单步、调速、快照、恢复、分叉和重启。暂停覆盖整棵子树，兄弟与祖先继续工作。任务管理器可修改总预算、进程上限和子系统拨付。逻辑工作包含解释指令与按数据规模计费的服务；WebGL 绘制和真实网页由宿主设备执行，不算作程序指令。运行状态每 4 秒保存到当前数据目录。</p><h3>NEX 程序格式</h3><p>程序是 .nx 文本，一行一条指令。表达式支持算术、比较、数组、对象、属性访问，以及 sin / cos / min / max / abs / sqrt / floor / len / number / string 等纯函数，不能访问宿主 DOM 或计时器。</p><pre>{`set i 0\nloop:\nset i i + 1\nprint i\nwait 100\nif i < 10 goto loop\nsys saved file.write {path:"/Documents/result.txt",content:string(i)}\nhalt`}</pre><p><code>receive value</code> 等待消息；<code>send {'{to:"pid-…",value:"你好"}'}</code> 发出独立值副本。<code>sys result process.start "/Programs/sum.nx"</code> 启动程序；file.read / file.write 读写本系统文件。time 与 pid 是当前虚拟时间和身份。挂起保留 PC、变量与队列，结束不再处理消息。</p><h3>可编辑内核与应用</h3><p>父系统 /System/inner-N.kernel.nx 是对应子系统真正执行的内核程序。可在「系统空间」点击代码图标打开，修改 quantum、policy（round-robin / reverse）、messageMode（fifo / lifo）后保存并重启。调度循环、等待与唤醒、系统调用分派、文件配额判断、消息规则在源文件中。编译器入口 /System/compiler.nx；运行后安装新编译约束。桌面与应用入口在 /System/desktop.nx、application.nx、player.nx、scene.nx、effects.nx 与 chart.nx。</p><h3>飞行排演与场景资源</h3><p>默认演出 15 秒，30 FPS 取样，所有模型、材质、灯光、节点和轨迹在 /Demo/helicopter-24.scene。/Demo/minimal.scene 是一个物体、一盏灯、一台相机的最小示例。场景支持 sphere / box / cylinder / cone / torus / text / group 和部件层级。motion 是关于 t、x、y、z 的纯表达式。</p><p>播放器右上角设置可开始排演。飞控文件 /Programs/flight-control.nx 读取 flight.sensor，使用 flight.control 写入 collective 与 cyclic。传感器包含位置、速度、姿态、目标与时间戳。挂起飞控后物理继续，失稳会导致接触；降低预算会拉长控制周期。保存记录为 .flight，可从文件管理器重开、跳转与续演。</p><h3>文件、数据与快照</h3><p>工作簿 .sheet 是 JSON，包含 title、cells（含原始公式）与 format。公式支持四则运算、括号、引用与 SUM，错误显示 #DIV/0!、#REF!、#CYCLE!。选区支持 Shift、拖动、Ctrl+C/V/Z/Y。图表显式连接已打开的工作簿，关闭数据源保留缓存。暂停时更新暂存在源端。</p><p>跨层拖放复制独立文件，同名可确认覆盖。导入与导出通过文件工具栏完成。快照存放在父系统 /Snapshots，保存系统树、PC、变量、队列、未完成工作、文件、桌面、播放器与图表。恢复后图表等待重新连接；分叉生成新身份且不继承范围外订阅。</p><div className="help-tip"><CheckCircle2 size={20}/><span>更完整的实现边界、文件格式与自动化接口见项目根目录 README.md 与 automation.json。</span></div></div></div>}

function ProgramDisplay({process,systemId}){const d=process.display;if(d.kind==='3d')return<div className="program-display"><SceneView data={{position:0,effectTime:d.frame?.t||0,mode:'show',camera:'cinematic',orbit:{distance:15,azimuth:.6,elevation:.4},physics:{},...d}} onAction={(action,value)=>engine.send(systemId,process.id,{action,value})}/></div>;return<div className="program-display"><svg viewBox={'0 0 '+(d.width||480)+' '+(d.height||200)} style={{background:d.background||'#f0f5ed'}} onClick={e=>{const r=e.currentTarget.getBoundingClientRect();engine.send(systemId,process.id,{type:'pointer',x:(e.clientX-r.left)/r.width*(d.width||480),y:(e.clientY-r.top)/r.height*(d.height||200)})}}>{(d.shapes||[]).map((n,i)=>n.type==='circle'?<circle key={i} cx={n.x} cy={n.y} r={n.r} fill={n.fill}/>:n.type==='rect'?<rect key={i} x={n.x} y={n.y} width={n.width} height={n.height} fill={n.fill}/>:n.type==='line'?<line key={i} x1={n.x} y1={n.y} x2={n.x2} y2={n.y2} stroke={n.stroke||n.fill}/>:n.type==='text'?<text key={i} x={n.x} y={n.y} fontSize={n.size||16} fill={n.fill}>{n.text}</text>:null)}</svg></div>}

